// WSET-style 5-step scales (index 1..5).
const LEVELS = {
  en: ['low', 'medium(−)', 'medium', 'medium(+)', 'high'],
  de: ['niedrig', 'mittel(−)', 'mittel', 'mittel(+)', 'hoch'],
};
const SCALES = {
  colour: { en: ['pale', 'medium(−)', 'medium', 'medium(+)', 'deep'], de: ['blass', 'mittel(−)', 'mittel', 'mittel(+)', 'tief'] },
  sweetness: { en: ['dry', 'off-dry', 'medium', 'sweet', 'luscious'], de: ['trocken', 'halbtrocken', 'lieblich', 'süß', 'edelsüß'] },
  acidity: LEVELS,
  tannin: LEVELS,
  alcohol: LEVELS,
  body: { en: ['light', 'medium(−)', 'medium', 'medium(+)', 'full'], de: ['leicht', 'mittel(−)', 'mittel', 'mittel(+)', 'voll'] },
};
const PROPS = ['colour', 'sweetness', 'acidity', 'tannin', 'alcohol', 'body'];

const FLAGS = {
  'France': '🇫🇷', 'Italy': '🇮🇹', 'Spain': '🇪🇸', 'Portugal': '🇵🇹', 'Germany': '🇩🇪', 'Austria': '🇦🇹', 'Hungary': '🇭🇺',
  'USA': '🇺🇸', 'Canada': '🇨🇦', 'Chile': '🇨🇱', 'Argentina': '🇦🇷', 'Australia': '🇦🇺', 'New Zealand': '🇳🇿', 'South Africa': '🇿🇦',
};

// Overview sections, in syllabus order. `lo` drives the filter chips.
const SECTIONS = [
  { key: 'principalBlack', lo: 'lo3', test: i => i.group === 'principal' && i.kind === 'black' },
  { key: 'principalWhite', lo: 'lo3', test: i => i.group === 'principal' && i.kind === 'white' },
  { key: 'regionalBlack', lo: 'lo4', test: i => i.group === 'regional' && i.kind === 'black' },
  { key: 'regionalWhite', lo: 'lo4', test: i => i.group === 'regional' && i.kind === 'white' },
  { key: 'sparklingGrapes', lo: 'lo5', test: i => i.group === 'sparkling' },
  { key: 'sparklingWines', lo: 'lo5', test: i => i.group === 'wine' && i.kind === 'sparkling' },
  { key: 'fortifiedWines', lo: 'lo5', test: i => i.group === 'wine' && i.kind === 'fortified' },
];

const state = {
  lang: loadLang(),
  aromas: {},   // EN aroma -> DE translation
  items: [],    // in SECTIONS order
  filter: 'all',
  query: '',
};

const $ = id => document.getElementById(id);
const t = key => I18N[state.lang][key];
const aroma = a => (state.lang === 'de' ? state.aromas[a] || a : a);
const byId = id => state.items.find(i => i.id === id);

// Small DOM helper: el('a', { href: '#', class: 'x' }, 'text', childNode, ...)
function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v === null || v === undefined || v === false) continue;
    if (k === 'class') node.className = v;
    else node.setAttribute(k, v);
  }
  for (const c of children.flat()) {
    if (c === null || c === undefined || c === false) continue;
    node.append(c instanceof Node ? c : String(c));
  }
  return node;
}

function scaleText(prop, range) {
  const labels = SCALES[prop][state.lang];
  const [a, b] = range;
  return a === b ? labels[a - 1] : `${labels[a - 1]} – ${labels[b - 1]}`;
}

// 5-segment meter with the range [a, b] filled.
function meter(prop, range, small = false) {
  const cls = `meter meter-${prop}${small ? ' small' : ''}`;
  if (!range) return el('span', { class: `${cls} empty`, role: 'img', 'aria-label': t('none') }, t('none'));
  const node = el('span', { class: cls, role: 'img', 'aria-label': `${t('prop_' + prop)}: ${scaleText(prop, range)}` });
  for (let i = 1; i <= 5; i++) node.append(el('span', { class: i >= range[0] && i <= range[1] ? 'seg on' : 'seg' }));
  return node;
}

function matches(item, q) {
  if (!q) return true;
  const hay = [
    item.name, ...item.synonyms, ...item.terms,
    ...item.regions.flatMap(r => [r.country, COUNTRIES[r.country] || '', ...r.gis]),
    ...Object.values(item.aromas).flat().flatMap(a => [a, state.aromas[a] || '']),
  ].join(' ').toLowerCase();
  return q.toLowerCase().split(/\s+/).every(word => hay.includes(word));
}

// ---- Overview ----

function renderFilter() {
  $('kind-filter').replaceChildren(...['all', 'lo3', 'lo4', 'lo5'].map(key => {
    const btn = el('button', { type: 'button', class: key === state.filter ? 'chip active' : 'chip', 'aria-pressed': String(key === state.filter) }, t(key));
    btn.addEventListener('click', () => { state.filter = key; renderOverview(); });
    return btn;
  }));
}

function tile(item) {
  const structureProp = item.structure.tannin ? 'tannin' : 'sweetness';
  const flags = [...new Set(item.regions.map(r => r.country))].map(c => FLAGS[c] || '').join(' ');
  return el('a', { href: `#/${item.id}`, class: `tile kind-${item.kind}` },
    el('span', { class: 'tile-name' }, item.name),
    item.synonyms.length ? el('span', { class: 'tile-syn' }, item.synonyms.join(' · ')) : null,
    el('span', { class: 'tile-meters' },
      ...['acidity', structureProp, 'body'].map(p =>
        el('span', { class: 'tile-meter' }, el('span', { class: 'tile-label' }, t('short_' + p)), meter(p, item.structure[p], true)))),
    el('span', { class: 'tile-flags', 'aria-hidden': 'true' }, flags));
}

function renderOverview() {
  renderFilter();
  let shown = 0;
  $('groups').replaceChildren(...SECTIONS.map(section => {
    if (state.filter !== 'all' && state.filter !== section.lo) return null;
    const items = state.items.filter(i => section.test(i) && matches(i, state.query));
    if (!items.length) return null;
    shown += items.length;
    return el('section', { class: 'group' },
      el('h3', {}, t(section.key), el('span', { class: 'count' }, items.length)),
      el('div', { class: 'tiles' }, items.map(tile)));
  }).filter(Boolean));
  $('empty').hidden = shown > 0;
}

// ---- Detail ----

function chips(list, cls) {
  return el('div', { class: 'chips' }, list.map(x => el('span', { class: `chip ${cls}` }, x)));
}

function section(title, ...content) {
  return el('section', { class: 'profile-section' }, el('h3', {}, title), ...content);
}

function renderDetail(item) {
  const idx = state.items.indexOf(item);
  const prev = state.items[idx - 1];
  const next = state.items[idx + 1];
  const nav = () => el('nav', { class: 'detail-nav' },
    el('a', { href: '#/' }, t('back')),
    el('span', { class: 'prevnext' },
      prev ? el('a', { href: `#/${prev.id}`, title: prev.name }, t('prev')) : el('span', { class: 'disabled' }, t('prev')),
      next ? el('a', { href: `#/${next.id}`, title: next.name }, t('next')) : el('span', { class: 'disabled' }, t('next'))));

  const head = el('header', { class: `profile-head kind-${item.kind}` },
    el('div', { class: 'badges' },
      el('span', { class: 'badge kind' }, t('kind_' + item.kind)),
      el('span', { class: 'badge lo' }, t('group_' + item.group))),
    el('h2', {}, item.name),
    item.synonyms.length ? el('p', { class: 'syn' }, `${t('alsoKnown')}: ${item.synonyms.join(', ')}`) : null);

  const facts = section(t('keyFacts'), el('ul', { class: 'facts' }, item.notes[state.lang].map(n => el('li', {}, n))));

  const structure = section(t('structure'), el('table', { class: 'structure' }, el('tbody', {},
    PROPS.map(p => el('tr', {},
      el('th', { scope: 'row' }, t('prop_' + p)),
      el('td', { class: 'meter-cell' }, meter(p, item.structure[p])),
      el('td', { class: 'scale-text' }, item.structure[p] ? scaleText(p, item.structure[p]) : t('none')))))));

  const layer = (key, emptyKey) => {
    const list = item.aromas[key];
    return el('tr', { class: `aroma-${key}` },
      el('th', { scope: 'row' }, t(key), el('small', {}, t(key + 'Sub'))),
      el('td', {}, list.length ? chips(list.map(aroma), `aroma ${key}`) : el('span', { class: 'muted' }, t(emptyKey))));
  };
  const aromas = section(t('aromas'), el('table', { class: 'aromas' }, el('tbody', {},
    layer('primary', 'none'), layer('secondary', 'noSecondary'), layer('tertiary', 'noTertiary'))));

  const regions = section(t('regions'), el('table', { class: 'regions' }, el('tbody', {},
    item.regions.map(r => el('tr', {},
      el('th', { scope: 'row' }, el('span', { class: 'flag', 'aria-hidden': 'true' }, FLAGS[r.country] || ''), countryLabel(r.country, state.lang)),
      el('td', {}, chips(r.gis, 'gi')))))));

  const terms = section(t('terms'), item.terms.length ? chips(item.terms, 'term') : el('p', { class: 'muted' }, t('none')));

  const grapes = item.grapes.length
    ? section(t('grapes'), el('div', { class: 'chips' }, item.grapes.map(g => {
        const grape = byId(g);
        return el('a', { href: `#/${g}`, class: `chip grape-link kind-${grape.kind}` }, grape.name);
      })))
    : null;

  $('detail').className = `profile kind-${item.kind}`;
  $('detail').replaceChildren(...[nav(), head, facts, structure, aromas, regions, terms, grapes, nav()].filter(Boolean));
  document.title = `${item.name} · WSET`;
}

// ---- Routing & wiring ----

function route() {
  const id = decodeURIComponent(location.hash.replace(/^#\/?/, ''));
  const item = id && byId(id);
  $('overview').hidden = !!item;
  $('detail').hidden = !item;
  if (item) {
    renderDetail(item);
    window.scrollTo(0, 0);
  } else {
    document.title = 'WSET Library';
    renderOverview();
  }
}

function render() {
  document.documentElement.lang = state.lang;
  for (const btn of document.querySelectorAll('.lang button')) {
    btn.classList.toggle('active', btn.dataset.lang === state.lang);
  }
  for (const node of document.querySelectorAll('[data-i18n]')) node.textContent = t(node.dataset.i18n);
  for (const node of document.querySelectorAll('[data-i18n-placeholder]')) node.placeholder = t(node.dataset.i18nPlaceholder);
  if (state.items.length) route();
}

for (const btn of document.querySelectorAll('.lang button')) {
  btn.addEventListener('click', () => {
    state.lang = btn.dataset.lang;
    saveLang(state.lang);
    render();
  });
}
$('search').addEventListener('input', e => { state.query = e.target.value.trim(); renderOverview(); });
window.addEventListener('hashchange', route);

async function init() {
  render();
  try {
    const res = await fetch('library.json', { cache: 'no-store' });
    if (!res.ok) throw new Error(res.status);
    const data = await res.json();
    state.aromas = data.aromas;
    state.items = SECTIONS.flatMap(s => data.items.filter(s.test));
  } catch {
    $('error').textContent = t('loadError');
    $('error').hidden = false;
    return;
  }
  render();
}

init();
